//------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------ 
//	NAME:			HE_LightControl                                                                                                                                                                                                                                                                           
//	CREATOR:		Helgevold - William Veim                                                                                                                                                                                                                                                              
//                                                                                                                                                                                                                                                                                                                            
//------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------ 
//  VERSION LOG:                                                                                                                                                                                                                                                                                                   
//	VERSION		DATE				SIGN						DESCRIPTION                                                                                                                                                                                     
//	1.0.0				2026-05-22		Ruben Byman			Initial release
//
//===============================================================================================================================
//
//		DESCRIPTION:
//		Wrapper for using adfweb HD67840 Ethernet/IP to DALI gw
//		Implements HE_LightControl_Logic
//
//================================================================================================================================

 (*************************************************************************
 *	INITIALIZE VARIABELS
 *************************************************************************)

Ext_LightControl.EXT_General.LocationIndex[0]:=Cfg_MainLocation; //First index / main location is forced; remaining tree optional can be set in SCADA

IF NOT Ext_LightControl.INT_Data.Initialise THEN
	
	//Common parameters are initialised in logic block
	
	//State config
	Ext_LightControl.EXT_Engineering.StateCfg_3.Cfg_Quality:=0; //Communication Fault = Diagnostic
	Ext_LightControl.EXT_Engineering.StateCfg_3.Cfg_Alarm:=TRUE; //Communication Fault = Alarm
	
	//Initialise set true in logic block
	
END_IF;

(*************************************************************************
 *	UPDATE INPUT PARAMETERS
 *************************************************************************)

FB_LightControl_Logic.Inp_AlmSuppress:=Inp_AlmSuppress;
FB_LightControl_Logic.Inp_AlmSuppressDesc:=Inp_AlmSuppressDesc;
FB_LightControl_Logic.Inp_Interlock:=Inp_Interlock;
FB_LightControl_Logic.Inp_Voltage_State:=Inp_Voltage_State;

(*************************************************************************
 *	UPDATE CONFIG PARAMETERS
 *************************************************************************)

FB_LightControl_Logic.Cfg_UPS_Present:=Cfg_UPS_Present;
FB_LightControl_Logic.Cfg_ControllerName:=Cfg_ControllerName;
FB_LightControl_Logic.Cfg_UPS_Present:=Cfg_UPS_Present;
FB_LightControl_Logic.Cfg_Interlock_InUse:=Cfg_Interlock_InUse;

(*************************************************************************
 *	UPDATING STATE CONTROL PARAMTERS
 *************************************************************************)

//STATE 1 - Locked to "Config Fault"
//STATE 2 - Locked to "Interlock"
 
Wrk_CommFault := HE_CommFault(PORT:=Cfg_EIP_Interface, IP:=Cfg_IP);
 
FB_LightControl_Logic.Cfg_State3_InUse:= 	TRUE;
FB_LightControl_Logic.Inp_State3_Desc:=		'Communication fault';
FB_LightControl_Logic.Inp_State3_State:= 		Wrk_CommFault;

FB_LightControl_Logic.Cfg_State4_InUse:= 	FALSE;
FB_LightControl_Logic.Inp_State4_Desc:=		'NOT IN USE';
FB_LightControl_Logic.Inp_State4_State:=		FALSE;

FB_LightControl_Logic.Cfg_State5_InUse:= 	FALSE;
FB_LightControl_Logic.Inp_State5_Desc:=		'NOT IN USE';
FB_LightControl_Logic.Inp_State5_State:=		FALSE;
 

(*************************************************************************
 *	EXCECUTING LOGIC BLOCK
 *************************************************************************)
 
FB_LightControl_Logic(ENS:=TRUE, 
										Ext_LightControl:=	Ext_LightControl, 
										Int_Alarm:=				Int_Alarm);

(*************************************************************************
 *	UPDATING FB OUTPUT
 *************************************************************************)			
 
//BLOCK OUTPUT
Sts_Alarm :=  					FB_LightControl_Logic.Sts_Alarm;
Sts_LightStarted := 			FB_LightControl_Logic.Sts_LightStarted;
Sts_LightMax := 				FB_LightControl_Logic.Sts_LightMax;
Out_Output :=					FB_LightControl_Logic.Out_Output;
Out_ByteOutput :=			FB_LightControl_Logic.Out_ByteOutput;
